const STORE={listings:'slither-listings-v1',likes:'slither-likes-v1',cart:'slither-cart-v1',messages:'slither-messages-v1',seller:'slither-seller-v1',signup:'slither-signup-v1',theme:'slither-theme-v1',profile:'slither-profile-v1',known:'slither-known-v1'};
const get=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
const set=(key,value)=>localStorage.setItem(key,JSON.stringify(value));
const all=()=>[...SEED,...get(STORE.listings,[])];
const safe=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'$'+Number(n).toLocaleString('en-US',{maximumFractionDigits:2});
const state={query:'',category:'All art',sort:'Featured',chatTo:'Nova Reyes'};
const go=path=>{location.hash=path;window.scrollTo({top:0,behavior:'instant'});render()};
const likes=()=>get(STORE.likes,[]);const cart=()=>get(STORE.cart,[]);
let toastTimer;function toast(s){let el=document.getElementById('toast');el.textContent=s;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2800)}
function header(){return `<div class="topbar">THE NEXT GENERATION ART MARKETPLACE <span>✦ CREATE LOUDER ✦</span></div><header><div class="shell nav"><a class="brand" href="#/"><svg class="brand-snake" viewBox="0 0 74 28" aria-hidden="true"><path d="M4 22 Q12 9 21 18 Q28 25 36 17 T46 13" fill="none" stroke="#fff" stroke-width="5" stroke-linecap="round"/><path d="M46 18.5 Q43.5 12 47 6.8 Q52 3.2 57.2 6.4 Q63.2 9.6 63.6 12.6 Q63.2 16.2 57.6 18.8 Q51 21.2 46 18.5 Z" fill="#fff"/><path d="M56.3 9.8 L57.1 14.6" stroke="#14092b" stroke-width="1.9" stroke-linecap="round"/><path d="M63.6 12.6 L67.4 12.1 M67.4 12.1 L70.8 8.9 M67.4 12.1 L71 15.3" fill="none" stroke="#FF6B57" stroke-width="2" stroke-linecap="round"/></svg>PAINTED PYTHON</a><nav class="navlinks"><a href="#/explore">EXPLORE ART</a><a href="#/sell">SELL YOUR ART</a><a href="#/artists">ARTISTS</a><a href="#/top">TOP SELLERS</a><a href="#/membership">MEMBERSHIP</a><a href="#/creator">MEET THE CREATOR</a></nav><div class="navright"><button class="small-btn" data-action="messages">✉ <span class="hide-mobile">MESSAGES</span></button><button class="navicon" title="Saved art" aria-label="Saved art" data-action="saved">♡<span class="count">${likes().length}</span></button><button class="navicon" title="Cart" aria-label="Cart" data-action="cart">🛒<span class="count">${cart().length}</span></button><button class="navicon" id="themeBtn" title="Switch light / dark mode" aria-label="Switch light or dark mode" data-action="theme">${get(STORE.theme,'dark')==='light'?'🌙':'☀️'}</button><button class="navicon" title="My account" aria-label="My account" data-action="account">👤</button>${get(STORE.signup,null)?'':'<button class="small-btn" data-action="login">LOG IN</button>'}<button class="primary" style="padding:12px 17px;font-size:12px" data-action="start-selling">SELL ART ↗</button></div></div></header>`}
function footer(){return `<footer class="footer"><div class="shell footerflex"><div><a href="#/" class="brand"><svg class="brand-snake" viewBox="0 0 74 28" aria-hidden="true"><path d="M4 22 Q12 9 21 18 Q28 25 36 17 T46 13" fill="none" stroke="#fff" stroke-width="5" stroke-linecap="round"/><path d="M46 18.5 Q43.5 12 47 6.8 Q52 3.2 57.2 6.4 Q63.2 9.6 63.6 12.6 Q63.2 16.2 57.6 18.8 Q51 21.2 46 18.5 Z" fill="#fff"/><path d="M56.3 9.8 L57.1 14.6" stroke="#14092b" stroke-width="1.9" stroke-linecap="round"/><path d="M63.6 12.6 L67.4 12.1 M67.4 12.1 L70.8 8.9 M67.4 12.1 L71 15.3" fill="none" stroke="#FF6B57" stroke-width="2" stroke-linecap="round"/></svg>PAINTED PYTHON</a><p>SLITHER INTO CREATIVITY.<br>For artists. For the curious. For everybody who creates.</p></div><div class="footnav"><a href="#/explore">Explore</a><a href="#/sell">Sell</a><a href="#/membership">Membership</a><a href="#/messages">Messages</a><a href="#/top">Top Sellers</a><a href="#/creator">Meet the Creator</a></div></div><div class="shell" style="margin-top:35px;border-top:1px solid #3d3150;padding-top:18px"><p>© 2026 Painted Python. Creative marketplace concept. Demo purchases and memberships are not live.</p></div></footer>`}
const artLook=a=>`background:${safe(a.bg)}`;
function artCard(a){return `<article class="art-card"><a href="#/art/${a.id}" aria-label="View ${safe(a.title)}"><div class="art-img" style="${artLook(a)}"><div class="art-overlay"></div><span class="art-symbol">${safe(a.symbol)}</span><span class="tag">${safe(a.tag)}</span></div></a><div class="art-body"><h3>${safe(a.title)}</h3><div class="meta">by ${safe(a.artist)} · ${safe(a.category)}</div><div class="art-bottom"><strong class="price">${money(a.price)}</strong><div class="art-actions"><button data-action="like" data-id="${a.id}" aria-label="Save artwork">${likes().includes(a.id)?'♥':'♡'}</button><button data-action="add" data-id="${a.id}">ADD +</button></div></div></div></article>`}
function home(){return `<section class="hero"><div class="shell"><div class="eyebrow">✦ Where the extraordinary gets discovered</div><h1><span class="paint">SLITHER</span><br>INTO CREATIVITY.</h1><h2>ART WITH NO RULES. ARTISTS WITH NO LIMITS.</h2><p>A wild new home for independent artists. Show what you make, meet the people who love it, and turn your creative energy into something bigger.</p><div class="actions"><a class="primary" href="#/sell">START SELLING ART ↗</a><a class="outline" href="#/explore">EXPLORE THE ART →</a></div><div class="proof"><span><b>✦</b> REAL ARTISTS</span><span><b>◉</b> DIRECT CONNECTION</span><span><b>∞</b> ENDLESS CREATIVITY</span></div></div></section>
<section class="section" style="padding-top:34px"><div class="shell two-col" style="align-items:center"><div><div class="eyebrow">From the creator's own hand</div><h2 class="section-title">MEET <span class="paint">PAINTY.</span></h2><p class="sub">Her name is <b style="color:#fff">Painty</b> — the rainbow python, drawn by Flower Mills, the artist who created Painted Python. Her rule for this place is simple: real art, by real artists, signed by the hand that made it. Starting with hers.</p><div class="row" style="display:flex;gap:10px;margin-top:16px;flex-wrap:wrap"><a class="primary" href="#/creator" style="text-decoration:none;padding:12px 18px;border-radius:12px">MEET THE CREATOR ↗</a><a class="outline" href="#/membership" style="text-decoration:none;padding:12px 18px;border-radius:12px">JOIN — LIKE THE SIGN SAYS →</a></div></div><div style="text-align:center"><img src="assets/flower-join-now.png" alt="Rainbow python artwork by Flower Mills holding a Join Now sign" style="width:100%;max-width:520px;display:block;margin:0 auto;filter:drop-shadow(0 22px 34px rgba(0,0,0,.6))"><p class="meta" style="margin-top:12px">“Join Now!” — starring <b style="color:#fff">Painty</b> · original artwork by <b style="color:#fff">Flower Mills</b>, Creator &amp; Founder. Piece #1 on Painted Python.</p></div></div></section>
<section class="section"><div class="shell"><div class="section-top"><div><div class="eyebrow">Find your obsession</div><h2 class="section-title">EVERY STYLE.<br><span class="paint">EVERY STORY.</span></h2></div><a class="text-link" href="#/explore">EXPLORE ALL ART ↗</a></div><div class="categories">${[['Painting','🎨'],['Digital Art','💫'],['Illustration','✒️'],['Photography','📸'],['Sculpture','🗿'],['Mixed Media','🧩'],['Custom Portraits','👤'],['Pet Portraits','🐾'],['All art','🐍']].map(([n,e])=>`<button class="category" data-action="category" data-cat="${safe(n)}"><span class="shape">${e}</span><strong>${safe(n)} ↗</strong></button>`).join('')}</div></div></section>
<section class="section alt"><div class="shell"><div class="section-top"><div><div class="eyebrow">The slither selection</div><h2 class="section-title">ART THAT <span class="paint">HITS DIFFERENT.</span></h2><p class="sub">Meet your next favorite artwork, then message its creator directly.</p></div><a class="text-link" href="#/explore">SHOP THE COLLECTION ↗</a></div><div class="art-grid">${all().slice(0,8).map(artCard).join('')}</div></div></section>
<section class="section"><div class="shell"><div class="banner"><div><div class="eyebrow">Calling every creator</div><h2>DON'T JUST MAKE ART.<br>MAKE MOVES.</h2><p>Your work deserves more than a scroll. Build your storefront, set your own prices, and connect directly with your buyers.</p></div><a class="primary" href="#/sell">OPEN YOUR STUDIO ↗</a></div></div></section><section class="section alt"><div class="shell"><div class="section-top"><div><div class="eyebrow">Three moves. Infinite possibilities.</div><h2 class="section-title">CREATE. <span class="paint">CONNECT.</span> SELL.</h2></div></div><div class="steps"><div class="step"><span class="number">01</span><h3>MAKE YOUR MARK</h3><p>Set up your artist identity and post work worth talking about.</p></div><div class="step"><span class="number">02</span><h3>START THE CONVERSATION</h3><p>Let collectors ask questions and get to know the artist behind each piece.</p></div><div class="step"><span class="number">03</span><h3>BUILD YOUR CREATIVE BUSINESS</h3><p>Set pricing, manage your gallery, and grow your audience on your terms.</p></div></div></div></section>`}
function explore(savedOnly=false){let items=all().filter(a=>(!savedOnly||likes().includes(a.id))&&(state.category==='All art'||a.category===state.category)&&(`${a.title} ${a.artist} ${a.category}`.toLowerCase().includes(state.query.toLowerCase())));if(state.sort==='Price: low to high')items.sort((a,b)=>a.price-b.price);if(state.sort==='Price: high to low')items.sort((a,b)=>b.price-a.price);if(state.sort==='Newest')items.reverse();return `<div class="page-hero"><div class="shell"><div class="eyebrow">DISCOVER YOUR NEXT OBSESSION</div><h1 class="page-title">${savedOnly?'YOUR SAVED':`EXPLORE THE <span class="paint">UNEXPECTED.</span>`}</h1><p class="sub">Original art. Electric perspectives. Real conversations with independent artists.</p></div></div><section class="section"><div class="shell"><div class="filters"><input class="field" id="searchArt" value="${safe(state.query)}" placeholder="Search artwork, creators, styles…" aria-label="Search artwork"><select id="catArt" aria-label="Category">${['All art','Painting','Digital Art','Illustration','Drawing & Sketch','Photography','Sculpture','Mixed Media','Collage','Printmaking','Prints & Posters','Ceramics','Textile & Fiber Art','Glass Art','Wood Art','Metal Art','Resin Art','Paper Art','Calligraphy & Lettering','Street Art & Murals','Tattoo Flash','Custom Portraits','Pet Portraits','Anime & Manga Style','3D & CGI Art','Cosplay','Pottery','Character Design','Commissions','Outfit Design'].map(n=>`<option ${n===state.category?'selected':''}>${n}</option>`).join('')}</select><select id="sortArt" aria-label="Sort artwork">${['Featured','Newest','Price: low to high','Price: high to low'].map(n=>`<option ${n===state.sort?'selected':''}>${n}</option>`).join('')}</select></div><div class="art-grid">${items.map(artCard).join('')}</div>${items.length?'':'<div class="empty">Nothing in this collection yet. Try another filter.</div>'}</div></section>`}
function detail(id){let a=all().find(x=>String(x.id)===String(id));if(!a)return notFound();return `<section class="section"><div class="shell two-col"><div class="detail-art" style="${artLook(a)}">${safe(a.symbol)}</div><div class="detail-side"><div class="eyebrow">${safe(a.category)} / ${safe(a.tag)}</div><h1>${safe(a.title)}</h1><div class="meta">An artwork by <strong style="color:#fff">${safe(a.artist)}</strong></div><div class="detail-price paint">${money(a.price)}</div><p>${safe(a.description)}</p><div class="chips"><span class="chip">✦ ${safe(a.medium)}</span><span class="chip">↗ Direct artist messaging</span><span class="chip">♡ Independent creator</span></div><div class="actions"><button class="primary" data-action="add" data-id="${a.id}">ADD TO CART +</button><button class="outline" data-action="contact" data-artist="${safe(a.artist)}">MESSAGE THE ARTIST ✉</button><button class="outline" data-action="like" data-id="${a.id}">${likes().includes(a.id)?'♥ SAVED':'♡ SAVE'}</button></div><div class="notice">Prototype listing: checkout is simulated. Real payments, shipping, and identity checks require production integration.</div></div></div></section><section class="section alt"><div class="shell"><div class="section-top"><h2 class="section-title">KEEP <span class="paint">EXPLORING.</span></h2></div><div class="art-grid">${all().filter(x=>x.id!==a.id).slice(0,4).map(artCard).join('')}</div></div></section>`}
function normName(u){return String(u||'').toLowerCase().replace(/0/g,'o').replace(/1/g,'i').replace(/3/g,'e').replace(/4/g,'a').replace(/5/g,'s').replace(/7/g,'t').replace(/@/g,'a').replace(/\$/g,'s')}
function usernameCheck(u){let raw=String(u||'').trim();if(raw.length<3||raw.length>20)return{ok:false,why:'short'};if(!/^[A-Za-z][A-Za-z0-9_.]*$/.test(raw))return{ok:false,why:'chars'};let n=normName(raw);let compact=n.replace(/[^a-z]/g,'');let hard=['fuck','shit','bitch','whore','slut','nigger','nigga','faggot','cunt','penis','vagina','porn','asshole','rape','pedophile','molester'];for(let w of hard){if(compact.indexOf(w)>=0)return{ok:false,why:'bad'}}let toks=n.split(/[^a-z]+/).filter(Boolean);let soft=['ass','dick','cock','sex','cum','tit','fag','nazi','kill'];for(let t of toks){if(soft.indexOf(t)>=0)return{ok:false,why:'bad'}}let reserved=['admin','support','official','paintedpython','painty','moderator','staff','flowermills','flower','owner','ceo'];if(reserved.indexOf(compact)>=0)return{ok:false,why:'reserved'};let taken=['novareyes','samrivera','riverquinn','kaisantos','arimoon','julescarter','milobanks','elimorgan'];if(taken.indexOf(compact)>=0)return{ok:false,why:'taken'};return{ok:true}}
function applyTheme(){let t=get(STORE.theme,'dark');if(document.body&&document.body.classList)document.body.classList.toggle('light',t==='light');let b=document.getElementById('themeBtn');if(b)b.textContent=t==='light'?'🌙':'☀️'}
applyTheme();
function bioCheck(t){let raw=String(t||'');if(/[^@\s]+@[^@\s]+\.[^@\s]+/.test(raw)||/(https?:\/\/|www\.)/i.test(raw)||/\b\d{3}[-.\s]\d{3}[-.\s]\d{4}\b/.test(raw)||/\b\d{7,}\b/.test(raw))return{ok:false,why:'contact'};let n=normName(raw.toLowerCase());let compact=n.replace(/[^a-z]/g,'');let hard=['fuck','shit','bitch','whore','slut','nigger','nigga','faggot','cunt','penis','vagina','porn','asshole','rape','killyourself','kys'];for(let w of hard){if(compact.indexOf(w)>=0)return{ok:false,why:'language'}}let toks=n.split(/[^a-z]+/).filter(Boolean);let soft=['ass','dick','cock','sex','cum','tit','fag','nazi'];for(let tk of toks){if(soft.indexOf(tk)>=0)return{ok:false,why:'language'}}return{ok:true}}
function picCheck(f){if(!f)return{ok:true};if(!/^image\//.test(f.type||''))return{ok:false,why:'type'};if(f.size>8*1024*1024)return{ok:false,why:'size'};return{ok:true}}
function avatarInner(example){let p=get(STORE.profile,{});if(!example&&p.avatar)return '<img src="'+p.avatar+'" alt="Profile picture" style="width:100%;height:100%;object-fit:cover;border-radius:50%">';return example?'🌈':'🐍'}
function ageFromDob(dob,now){let m=/^(\d{4})-(\d{2})-(\d{2})$/.exec(dob||'');if(!m)return null;let y=+m[1],mo=+m[2],d=+m[3];if(mo<1||mo>12||d<1||d>31)return null;let age=now.getFullYear()-y;let before=(now.getMonth()+1<mo)||((now.getMonth()+1===mo)&&(now.getDate()<d));if(before)age--;if(age<0||age>120)return null;return age}
function sell(){let seller=get(STORE.seller,{});return `<div class="page-hero"><div class="shell"><div class="eyebrow">Your creative takeover begins here</div><h1 class="page-title">YOUR ART. <span class="paint">YOUR STAGE.</span></h1><p class="sub">A storefront built for artists who refuse to blend in. Create a listing in this interactive demo.</p></div></div><section class="section"><div class="shell two-col"><div><div class="panel" style="margin-bottom:22px;border:2px solid #7a3cff"><h2 class="section-title" style="font-size:30px">JOIN PAINTED <span class="paint">PYTHON.</span></h2><p class="sub" style="margin-bottom:14px">Create your account to sell your art — and to buy from the artists you love. Painted Python is for <b style="color:#fff">teenagers and adults only: you must be 13 or older to join.</b></p>${get(STORE.signup,null)?`<p style="line-height:1.7"><b style="color:#7CFC9A">✔ You’re signed up</b> as <b style="color:#fff">${safe(get(STORE.signup,{}).email||'')}</b>${get(STORE.signup,{}).username?' · @'+safe(get(STORE.signup,{}).username):''}${get(STORE.signup,{}).pronouns?' · '+safe(get(STORE.signup,{}).pronouns):''} in this browser. Your artist stage is reserved — real accounts activate at launch.</p><div class="actions" style="margin-top:12px"><button class="outline" data-action="signup-reset">USE A DIFFERENT EMAIL</button></div>`:`<form id="signupForm" class="form-grid"><div class="form-group"><label for="suUsername">CREATE YOUR USERNAME *</label><input id="suUsername" class="field" name="username" placeholder="e.g. rainbow.rebel_ink" required maxlength="20"></div><div class="form-group"><label for="suEmail">EMAIL ADDRESS *</label><input id="suEmail" class="field" name="email" type="email" placeholder="you@example.com" required maxlength="120"></div><div class="form-group"><label for="suDob">DATE OF BIRTH *</label><input id="suDob" class="field" name="dob" type="date" required></div><div class="form-group"><label for="suPronouns">PRONOUNS *</label><select id="suPronouns" class="field" name="pronouns" required><option value="">Choose your pronouns</option><option>She/Her</option><option>He/Him</option><option>They/Them</option></select></div><div class="full"><button class="primary" type="submit">SIGN UP — CREATE MY ACCOUNT ✦</button><p id="signupMsg" style="margin-top:10px;line-height:1.6" role="alert"></p><p class="form-note">One account for artists and customers. Under 13? We’ll be here when you’re ready — Painted Python does not create accounts for children under 13. Already have an account? <a class="text-link" href="#/login">LOG IN</a></p></div></form>`}</div><h2 class="section-title">LIST YOUR NEXT <span class="paint">MASTERPIECE.</span></h2><p class="sub">Publish a demonstration artwork instantly. Listings are stored in this browser only until Muse connects the real platform.</p><div class="panel"><form id="listingForm" class="form-grid"><div class="form-group"><label for="artistName">ARTIST / STUDIO NAME *</label><input id="artistName" class="field" name="artist" value="${safe(seller.artist||'')}" placeholder="Your creative identity" required maxlength="70"></div><div class="form-group"><label for="artTitle">ARTWORK TITLE *</label><input id="artTitle" class="field" name="title" placeholder="Name your artwork" required maxlength="100"></div><div class="form-group"><label for="artCategory">CATEGORY *</label><select id="artCategory" name="category"><option>Painting</option><option>Digital Art</option><option>Illustration</option><option>Drawing & Sketch</option><option>Photography</option><option>Sculpture</option><option>Mixed Media</option><option>Collage</option><option>Printmaking</option><option>Prints & Posters</option><option>Ceramics</option><option>Textile & Fiber Art</option><option>Glass Art</option><option>Wood Art</option><option>Metal Art</option><option>Resin Art</option><option>Paper Art</option><option>Calligraphy & Lettering</option><option>Street Art & Murals</option><option>Tattoo Flash</option><option>Custom Portraits</option><option>Pet Portraits</option><option>Anime & Manga Style</option><option>3D & CGI Art</option><option>Cosplay</option><option>Pottery</option><option>Character Design</option><option>Commissions</option><option>Outfit Design</option></select></div><div class="form-group"><label for="artPrice">PRICE (USD) *</label><input id="artPrice" class="field" name="price" type="number" min="1" max="100000" step="0.01" placeholder="250" required></div><div class="form-group"><label for="artMedium">MEDIUM / MATERIALS</label><input id="artMedium" class="field" name="medium" placeholder="Acrylic on canvas" maxlength="90"></div><div class="form-group"><label for="artEmoji">ARTWORK ICON (DEMO PREVIEW)</label><select id="artEmoji" name="symbol"><option>🎨</option><option>🐍</option><option>🌈</option><option>🌺</option><option>⚡</option><option>📸</option><option>💫</option><option>🗿</option></select></div><div class="form-group full"><label for="artDesc">TELL THE STORY *</label><textarea id="artDesc" name="description" placeholder="What inspired this piece? What should a buyer know?" required maxlength="900"></textarea></div><div class="form-group full"><label for="artColor">COLOR MOOD</label><select id="artColor" name="bg"><option value="linear-gradient(130deg,#fa2088,#4727c3,#07dff1)">Neon serpent</option><option value="linear-gradient(130deg,#ffb12b,#fa287f,#7638db)">Sunset fire</option><option value="linear-gradient(130deg,#02a4be,#9cf13e,#11266a)">Electric jungle</option></select></div><div class="full"><button class="primary" type="submit">PUBLISH DEMO LISTING ↗</button><p class="form-note">No images are uploaded in this front-end demo. Actual image upload, moderation, inventory, taxes, and payouts require backend services.</p></div></form></div></div><div class="panel" style="margin-bottom:20px"><h3 style="margin-bottom:6px">WHAT YOU'D KEEP</h3><p class="sub" style="margin-bottom:10px">The founder set our fees low on purpose. Move the price and see it plainly:</p><label for="keepPrice" style="font-size:12px;letter-spacing:1px">SALE PRICE — $<span id="keepVal">200</span></label><input id="keepPrice" type="range" min="25" max="2000" step="25" value="200" style="width:100%" oninput="keepCalc(this.value)"><div style="font-size:14px;line-height:1.9;margin-top:8px">Hatchling (free): keep <b id="keepH">$184</b><br>Python $9.99/mo: keep <b id="keepP">$190</b><br>Viper Vanguard $19.99/mo: keep <b id="keepV">$194</b></div><p class="form-note">Platform fee only: 8% / 5% / 3%. Payment processing shown separately at checkout — no surprises, ever.</p></div><aside><div class="artist-spot"><div class="artist-avatar">🐍</div><div><h3>THE FUTURE LOOKS LIKE YOU.</h3><p class="sub">Own your aesthetic. Set your prices. Connect with people who get your work.</p></div></div><div class="steps" style="display:block;margin-top:20px"><div class="step"><span class="number">01</span><h3>SHOW YOUR WORK</h3><p>Illustrate your creative style with a strong gallery and a clear story.</p></div><div class="step" style="margin-top:14px"><span class="number">02</span><h3>CHAT WITH COLLECTORS</h3><p>Answer questions about the artwork, availability, and inspiration.</p></div><div class="step" style="margin-top:14px"><span class="number">03</span><h3>BUILD YOUR FOLLOWING</h3><p>Give people a place to discover your next release.</p></div></div></aside></div></section>`}
function dashboard(){let own=get(STORE.listings,[]);return `<div class="page-hero"><div class="shell"><div class="eyebrow">Artist studio · demo</div><h1 class="page-title">YOUR CREATIVE <span class="paint">CONTROL ROOM.</span></h1></div></div><section class="section"><div class="shell"><div class="dashboard-grid"><div class="stat"><b>${own.length}</b><span>YOUR DEMO LISTINGS</span></div><div class="stat"><b>${money(own.reduce((n,a)=>n+a.price,0))}</b><span>SUM OF LIST PRICES (NOT SALES)</span></div><div class="stat"><b>0</b><span>PAID ORDERS — NOT CONNECTED</span></div></div><div class="section-top"><h2 class="section-title">YOUR <span class="paint">GALLERY.</span></h2><a class="primary" href="#/sell">+ NEW LISTING</a></div><div class="panel">${own.length?own.map(a=>`<div class="list-row"><div class="list-thumb" style="${artLook(a)}">${safe(a.symbol)}</div><div class="list-info"><strong>${safe(a.title)}</strong><small>${money(a.price)} · ${safe(a.category)}</small></div><a class="mini-btn" href="#/art/${a.id}">VIEW</a><button class="mini-btn" data-action="delete" data-id="${a.id}">DELETE</button></div>`).join(''):'<div class="empty">Your gallery is empty. Add your first artwork to begin.</div>'}</div></div></section>`}
function artists(){let names=[...new Set(all().map(a=>a.artist))];return `<div class="page-hero"><div class="shell"><div class="eyebrow">Meet the humans behind the art</div><h1 class="page-title">CREATORS WITH <span class="paint">NO LIMITS.</span></h1></div></div><section class="section"><div class="shell"><div class="art-grid">${names.map((n,i)=>`<div class="panel"><div class="artist-avatar" style="margin-bottom:15px">${['🌈','🐍','⚡','🎨','💫'][i%5]}</div><h3>${safe(n)}</h3><p class="meta">Independent artist · ${all().filter(a=>a.artist===n).length} artworks</p>${RATINGS[n]?`<div style="margin-top:6px">${stars(RATINGS[n].r)} <b style="color:#fff">${RATINGS[n].r}</b> <span class="meta">(${RATINGS[n].n} reviews)</span></div><div style="margin-top:6px">${ageBadge(AGES[n])}</div>`:""}<div class="actions"><button class="outline" data-action="contact" data-artist="${safe(n)}">MESSAGE ARTIST ✉</button></div></div>`).join('')}</div></div></section>`}
function creator(){return `<div class="page-hero"><div class="shell"><div class="eyebrow">The human behind the python</div><h1 class="page-title"><span class="paint">About Flower</span></h1><p class="sub">Painted Python was created by an artist, for artists.</p></div></div><section class="section"><div class="shell two-col"><div><h2 class="section-title">FLOWER <span class="paint">MILLS</span></h2><p class="sub" style="margin-bottom:14px">Creator &amp; Founder of Painted Python · Digital artist</p><p style="line-height:1.75;margin-bottom:14px">Flower Mills is a digital artist who dips her creativity into many things — and built Painted Python because artists deserved a home that treats them like the main event. No faceless listings. No fee games. A place where you can message the artist, ask about the piece, and own something personal.</p><p style="line-height:1.75;margin-bottom:14px">Her pricing philosophy runs the whole company: keep fees low, show the math plainly, and let artists keep what they earn. Hatchling is free forever because she insisted on it.</p><p style="line-height:1.75">Her own studio — <b>Flower Mills</b> — is Shop #1 on Painted Python, and her first piece is already home: Painty, the rainbow python watching over the front page.</p><p style="line-height:1.75;margin-bottom:14px">Flower is a Christian, queer, autistic artist with a lifelong passion for creativity and imagination. From a young age, she discovered her love for drawing, which eventually blossomed into a journey of self-taught artistry and imaginative creation.</p><p style="line-height:1.75;margin-bottom:14px">Alongside her passion for art, Flower developed a deep appreciation for reptiles, particularly snakes. Inspired by their vibrant colors, unique beauty, and often misunderstood nature, she hopes to challenge negative perceptions of snakes by celebrating them through art and creativity.</p><p style="line-height:1.75;margin-bottom:14px">Combining these passions, Flower created a snake-themed website dedicated to supporting artists and independent creators. Her mission is to provide a space where talented individuals can showcase their work, share their creativity, and earn money through their artistic abilities.</p><p style="line-height:1.75;margin-bottom:14px">Flower believes that art is a powerful kind of magic—one that deserves to be nurtured, shared, and celebrated. Through her platform, she hopes to empower fellow artists to embrace their talents, pursue their passions, and turn their imagination into something truly special.</p><div class="row" style="display:flex;gap:10px;margin-top:20px"><a class="primary" href="#/artists" style="text-decoration:none;padding:12px 18px;border-radius:12px">VISIT HER STUDIO ↗</a><a class="outline" href="#/membership" style="text-decoration:none;padding:12px 18px;border-radius:12px">SEE HOW SHE PRICED IT</a></div></div><aside><div class="panel" style="padding:12px;margin-bottom:16px"><img src="assets/flower-portrait.jpg" alt="Flower Mills, Creator and Founder of Painted Python" style="width:100%;display:block;border-radius:12px;aspect-ratio:4/4.6;object-fit:cover;object-position:center 22%"><p class="meta" style="margin-top:10px"><b style="color:#fff">Flower Mills</b> — Creator &amp; Founder of Painted Python. The artist behind the marketplace, and Shop #1.</p></div><div class="artist-spot"><img src="assets/flower-portrait.jpg" alt="Flower Mills" style="width:64px;height:64px;border-radius:50%;object-fit:cover;object-position:center 22%;flex:none"><div><h3>FLOWER MILLS</h3><p class="sub">Creator of Painted Python · Studio #1 · Founding artist — her real artwork becomes part of this site's design, chosen by her, credited to her, hers forever.</p></div></div><div class="panel" style="padding:14px;margin-top:16px"><img src="assets/flower-join-now.png" alt="Rainbow python artwork by Flower Mills holding a Join Now sign" style="width:100%;display:block;filter:drop-shadow(0 14px 22px rgba(0,0,0,.55))"><p class="meta" style="margin-top:10px">“Join Now!” — that's <b style="color:#fff">Painty</b>, the Painted Python herself. Her first piece on the site — drawn by Flower, signed LilFlower37.</p></div></aside></div></section>`}
function membership(){return `<div class="page-hero"><div class="shell"><div class="eyebrow">Grow on your own terms</div><h1 class="page-title">CLAIM YOUR <span class="paint">CREATIVE SPACE.</span></h1><p class="sub">Artist tiers locked by the founder (2026-10-23). Collectors: The Serpent Circle — $7.99/mo for early drops, first commission slots, and the collection vault.</p></div></div><section class="section"><div class="shell"><div class="membership">${[{name:'Hatchling',price:'Free',features:['5 live listings','Buyer messaging','Secure checkout (demo)','8% per sale — you keep $184 on $200'],cta:'START FREE'},{name:'Python',price:'$9.99',features:['Unlimited listings','Commissions + analytics','Direct artist-to-buyer messages','5% per sale — you keep $190 on $200'],cta:'GO PYTHON',popular:true},{name:'Viper Vanguard',price:'$19.99',features:['Everything in Python','Featured placement','Verified badge + live drop events','3% per sale — you keep $194 on $200'],cta:'GO VANGUARD'}].map(t=>`<div class="tier ${t.popular?'popular':''}"><div class="eyebrow">${t.popular?'✦ ARTIST FAVORITE':'CREATIVE ACCESS'}</div><h3>${t.name}</h3><div class="amount">${t.price}${t.price!=='Free'?'<span> / month (proposed)</span>':''}</div><ul>${t.features.map(f=>`<li>${f}</li>`).join('')}</ul><button class="${t.popular?'primary':'outline'}" data-action="tier" data-tier="${t.name}">${t.cta} ↗</button></div>`).join('')}</div><div class="notice">Demo only — no subscription, payment, or purchase can be completed here. Prices shown are the founder-approved tiers; billing activates with the production build.</div></div></section>`}
function messages(){let inbox=get(STORE.messages,{});let contacts=[...new Set([...all().map(a=>a.artist),...Object.keys(inbox)])];if(!contacts.includes(state.chatTo))state.chatTo=contacts[0]||'Artist';let msgs=inbox[state.chatTo]||[];return `<div class="page-hero"><div class="shell"><div class="eyebrow">Art starts the conversation</div><h1 class="page-title">TALK TO THE <span class="paint">CREATOR.</span></h1><p class="sub">Local demonstration inbox. Messages are stored only in your browser and are not delivered to real artists.</p></div></div><section class="section"><div class="shell"><div class="chat-layout"><aside class="chat-list"><p class="eyebrow">ARTIST CONVERSATIONS</p>${contacts.map(n=>`<button class="chat-contact ${n===state.chatTo?'active':''}" data-action="chat" data-artist="${safe(n)}">◉ &nbsp; ${safe(n)}</button>`).join('')}</aside><div class="chat-main"><div style="padding:19px;border-bottom:1px solid #43364f;font-weight:900">✉ ${safe(state.chatTo)} <small class="meta"> · DEMO CHAT</small></div><div class="chat-history">${msgs.length?msgs.map(m=>`<div class="bubble mine">${safe(m.text)}</div>`).join(''):'<div class="empty">Start a conversation about an artwork, a commission, or the creative process.</div>'}</div><form id="chatForm" class="chat-compose"><input class="field" name="text" placeholder="Ask about artwork or a commission…" required maxlength="1000"><button class="primary" type="submit">SEND ↗</button></form></div></div></div></section>`}
function basket(){let ids=cart(),items=ids.map(id=>all().find(a=>a.id===id)).filter(Boolean);return `<div class="page-hero"><div class="shell"><div class="eyebrow">Your next discoveries</div><h1 class="page-title">YOUR <span class="paint">CART.</span></h1></div></div><section class="section"><div class="shell checkout-rows"><div class="panel">${items.length?items.map(a=>`<div class="list-row"><div class="list-thumb" style="${artLook(a)}">${safe(a.symbol)}</div><div class="list-info"><strong>${safe(a.title)}</strong><small>${safe(a.artist)} · ${money(a.price)}</small></div><button class="mini-btn" data-action="remove" data-id="${a.id}">REMOVE</button></div>`).join(''):'<div class="empty">Your cart is ready for a little creative chaos. <a href="#/explore" class="text-link">Discover art →</a></div>'}</div>${items.length?`<div class="checkout-total"><span>Estimated subtotal</span><span>${money(items.reduce((s,a)=>s+a.price,0))}</span></div><div class="notice">Shipping, taxes, stock verification, fees, and real payment processing are not implemented.</div><button class="primary" data-action="checkout">CHECKOUT DEMO ↗</button>`:''}</div></section>`}
function notFound(){return `<section class="section"><div class="shell"><h1 class="page-title">NOT FOUND.</h1><a href="#/" class="primary">BACK TO SLITHER</a></div></section>`}

const RATINGS={'Nova Reyes':{r:4.9,n:47},'Sam Rivera':{r:4.9,n:38},'River Quinn':{r:4.8,n:41},'Kai Santos':{r:4.8,n:29},'Ari Moon':{r:4.7,n:33},'Jules Carter':{r:4.7,n:21},'Milo Banks':{r:4.6,n:18},'Eli Morgan':{r:4.6,n:12}};
const AGES={'Nova Reyes':24,'Sam Rivera':31,'River Quinn':28,'Kai Santos':17,'Ari Moon':22,'Jules Carter':26,'Milo Banks':35,'Eli Morgan':29};
function ageBadge(age,big){if(age===null||age===undefined||isNaN(age))return '';let extra=big?'font-size:13px;padding:7px 13px;':'';if(age<18)return '<span class="badge" style="background:#14507a;color:#bfe3ff;'+extra+'">🛡 MINOR · 13–17</span>';return '<span class="badge" style="background:#3a3f4a;color:#e6ebf2;'+extra+'">🛡 ADULT · 18+</span>'}
const REVIEWS={'Nova Reyes':[{q:'She messaged me back within the hour and sent progress photos the whole way. The portrait made my sister cry — in the good way.',b:'Maya R.',w:'Custom portrait'},{q:'Colors are even richer in person. Packed like it was glass and gold.',b:'Dev P.',w:'Original painting'}],'Sam Rivera':[{q:'I asked for a desert piece for my studio and he asked about my light before painting. Who does that? It is perfect.',b:'Jordan T.',w:'Original painting'},{q:'Second piece I have bought from Sam. Zero drama, all heart.',b:'Priya K.',w:'Original painting'}],'River Quinn':[{q:'My commission was a weird idea and River treated it like it mattered. It did. It does.',b:'Alex M.',w:'Commission'}],'Kai Santos':[{q:'Fast, kind, and the detail up close is unreal.',b:'Sam W.',w:'Original artwork'}],'Ari Moon':[{q:'Bought a print, came back for the original. That is the review.',b:'Lee C.',w:'Print, then original'}],'Jules Carter':[{q:'Great communication from the first message to delivery day.',b:'Robin D.',w:'Original artwork'}],'Milo Banks':[{q:'Bold, strange, exactly as promised.',b:'Kit A.',w:'Original artwork'}],'Eli Morgan':[{q:'First art purchase ever. Eli made it easy and the piece is stunning.',b:'Jo F.',w:'Original artwork'}]};
function stars(r){let f=Math.round(r);return '<span class="stars" aria-label="'+r+' out of 5 stars">'+'★'.repeat(f)+'☆'.repeat(5-f)+'</span>'}
function topSellers(){let names=[...new Set(all().map(a=>a.artist))].filter(n=>RATINGS[n]);names.sort((a,b)=>RATINGS[b].r-RATINGS[a].r||RATINGS[b].n-RATINGS[a].n);let medals=['🥇','🥈','🥉'];let rtitles=['World Serpent','Titanoboa','King Cobra'];let rcolors=['#FFC94D','#D7DCE6','#E39A5F'];let podium=names.slice(0,3).map((n,i)=>{let t=RATINGS[n];let rv=(REVIEWS[n]||[])[0];return '<div class="panel" style="text-align:center;padding:26px 20px"><div style="font-size:40px">'+medals[i]+'</div><div style="font-family:Cinzel Decorative,serif;font-size:21px;letter-spacing:1px;color:'+rcolors[i]+';margin-top:6px">#'+(i+1)+' '+rtitles[i]+'</div><div class="artist-avatar" style="margin:10px auto">'+['🌈','🐍','⚡','🎨','💫'][i%5]+'</div><h3 style="font-size:22px">'+safe(n)+'</h3><div style="margin-top:6px">'+ageBadge(AGES[n])+'</div><div style="margin:6px 0">'+stars(t.r)+' <b style="color:#fff">'+t.r+'</b></div><p class="meta">'+t.n+' customer reviews</p>'+(rv?'<p style="line-height:1.65;font-style:italic;margin-top:12px">“'+safe(rv.q)+'”</p><p class="meta">— '+safe(rv.b)+' · '+safe(rv.w)+'</p>':'')+'<div class="actions" style="justify-content:center"><button class="outline" data-action="contact" data-artist="'+safe(n)+'">MESSAGE ARTIST ✉</button></div></div>'}).join('');let rows=names.slice(3).map((n,i)=>{let t=RATINGS[n];let rv=(REVIEWS[n]||[])[0];return '<div class="panel" style="display:flex;gap:16px;align-items:flex-start;margin-bottom:12px"><div style="font-size:22px;font-weight:900;color:#fff;min-width:34px">#'+(i+4)+'</div><div style="flex:1"><h3>'+safe(n)+' '+ageBadge(AGES[n])+'</h3><div style="margin:4px 0">'+stars(t.r)+' <b style="color:#fff">'+t.r+'</b> <span class="meta">· '+t.n+' reviews</span></div>'+(rv?'<p style="line-height:1.6;font-style:italic">“'+safe(rv.q)+'”</p><p class="meta">— '+safe(rv.b)+' · '+safe(rv.w)+'</p>':'')+'</div><button class="outline" data-action="contact" data-artist="'+safe(n)+'">MESSAGE ✉</button></div>'}).join('');return '<div class="page-hero"><div class="shell" style="display:flex;gap:26px;align-items:center;flex-wrap:wrap"><div style="flex:1;min-width:270px"><div class="eyebrow">Rated by the people who bought the art</div><h1 class="page-title">TOP <span class="paint">SELLERS.</span></h1><p class="sub">The highest-rated artists on Painted Python, ranked by the customers who actually bought from them. Every rating comes from a completed order — no bought stars, no fake love. The top three hold serpent titles — World Serpent, Titanoboa, King Cobra — earned, never given.</p></div><img src="assets/flower-painty-crown.png" alt="Painty the rainbow python wearing a gold number one crown, by Flower Mills" style="width:min(290px,78vw);display:block;filter:drop-shadow(0 18px 28px rgba(0,0,0,.55))"></div></div><section class="section" style="padding-top:26px"><div class="shell"><div class="art-grid" style="margin-bottom:26px">'+podium+'</div>'+rows+'<div class="panel" style="margin-top:22px"><h3>How ratings work</h3><div class="steps" style="margin-top:12px"><div class="step"><b>1</b><h4>Order completes</h4><p>Only customers whose order was delivered can rate the artist — 1 to 5 stars, plus a written review.</p></div><div class="step"><b>2</b><h4>Reviews stay honest</h4><p>Reviews live on the artist’s record permanently. Artists can reply, but never edit or delete what a customer said.</p></div><div class="step"><b>3</b><h4>The board ranks itself</h4><p>Top Sellers sorts by average rating, with review count breaking ties. Care for your customers and the board notices.</p></div></div><p class="meta" style="margin-top:14px">Preview board: ratings and reviews go live with real orders at launch — the artists and reviews shown here demonstrate exactly how the board will look and work.</p></div></div></section>'}

function login(){let known=get(STORE.known,null);return `<div class="page-hero"><div class="shell"><div class="eyebrow">Welcome back</div><h1 class="page-title">STEP BACK <span class="paint">IN.</span></h1><p class="sub">Your stage is right where you left it.</p></div></div><section class="section"><div class="shell"><div class="panel" style="max-width:560px;margin:auto">${known?`<h2 class="section-title" style="font-size:30px">LOG <span class="paint">IN.</span></h2><p class="sub" style="margin:10px 0 16px">An account lives on this device: <b style="color:#fff">@${safe(known.username||'')}</b>. Confirm it's you and step back in.</p><form id="loginForm" class="form-grid"><div class="form-group full"><label for="liEmail">EMAIL ADDRESS *</label><input id="liEmail" class="field" name="email" type="email" placeholder="you@example.com" required></div><div class="form-group full"><label for="liUsername">USERNAME *</label><input id="liUsername" class="field" name="username" placeholder="your.username" required></div><div class="full"><button class="primary" type="submit" style="width:100%">LOG IN ✦</button><p id="loginMsg" style="margin-top:10px;line-height:1.6" role="alert"></p></div></form>`:`<h2 class="section-title" style="font-size:30px">NO ACCOUNT <span class="paint">YET.</span></h2><p class="sub" style="margin:10px 0 16px">There's no account on this device yet. Create yours — guarded username, pronouns, the whole doorway — and it takes about a minute.</p><a class="primary" href="#/sell" style="text-decoration:none;display:inline-block">CREATE YOUR ACCOUNT →</a>`}</div></div></section>`}
function account(){let acct=get(STORE.signup,null);let example=!acct;let name=example?'Nova Reyes':(acct.username||'Your Studio');let handle=example?'@novareyes':(acct.username?'@'+acct.username:'');let email=example?'nova@novareyes.art':acct.email;let mine=example?all().filter(a=>a.artist==='Nova Reyes'):get(STORE.listings,[]);let rating=example?RATINGS['Nova Reyes']:null;let pr=example?'She/Her':(acct.pronouns||'');let photos=(mine.length?mine:all()).slice(0,6);let feed=mine.length?mine:all().slice(0,2);let posts=feed.map(a=>'<div class="panel" style="margin-bottom:16px"><div style="display:flex;gap:10px;align-items:center;margin-bottom:12px"><div class="artist-avatar" style="width:42px;height:42px;font-size:20px;overflow:hidden">'+avatarInner(example)+'</div><div><b style="color:#fff">'+safe(name)+'</b><p class="meta">'+safe(a.tag||'Just listed')+' · '+safe(a.category)+'</p></div></div>'+artCard(a)+'</div>').join('');return '<section class="section" style="padding-top:22px"><div class="shell"><div style="height:190px;border-radius:18px;background-image:url(assets/scales-bg-ballpython.jpg);background-size:cover;background-position:center;border:1px solid #3d3150"></div><div style="display:flex;gap:18px;align-items:flex-end;flex-wrap:wrap;padding:0 14px;margin-top:-52px"><div class="artist-avatar" style="width:118px;height:118px;font-size:56px;border:4px solid #17102a;background:#241843;overflow:hidden">'+avatarInner(example)+'</div><div style="flex:1;min-width:230px;padding-bottom:6px"><h1 class="page-title" style="font-size:42px">'+safe(name)+'</h1><p class="meta" style="margin-top:2px">'+safe(email)+' · '+(example?'Digital artist · Serpent Circle':'Artist studio')+(handle?' · '+safe(handle):'')+(pr?' · '+safe(pr):'')+'</p><div style="margin-top:9px">'+ageBadge(example?AGES[name]:ageFromDob(acct.dob,new Date()),true)+'</div><div style="margin-top:8px;display:flex;gap:8px;flex-wrap:wrap"><span class="badge">PYTHON MEMBER</span>'+(example?'<span class="badge" style="background:#FFC94D;color:#241203">#1 WORLD SERPENT 👑</span>':'<span class="badge" style="background:#1d5c38;color:#b8ffd2">13+ VERIFIED ✔</span>')+'</div></div><div style="display:flex;gap:10px;padding-bottom:10px"><a class="primary" href="#/sell" style="text-decoration:none;padding:12px 18px;border-radius:12px">+ ADD ARTWORK</a><a class="outline" href="#/messages" style="text-decoration:none;padding:12px 18px;border-radius:12px">MESSAGES ✉</a>'+(example?'':'<button class="outline" data-action="logout" style="padding:12px 18px;border-radius:12px">LOG OUT</button>')+'</div></div><div style="display:flex;gap:6px;flex-wrap:wrap;border-top:1px solid #3d3150;border-bottom:1px solid #3d3150;padding:10px 6px;margin-top:8px"><button class="small-btn" data-action="scrollto" data-target="acct-feed">Listings</button><button class="small-btn" data-action="scrollto" data-target="acct-intro">About</button><button class="small-btn" data-action="scrollto" data-target="acct-orders">Orders</button><button class="small-btn" data-action="scrollto" data-target="acct-reviews">Reviews</button><span class="meta" style="margin-left:auto;align-self:center">'+mine.length+' listings · '+(example?'3':'0')+' orders · '+likes().length+' saved</span></div>'+(example?'<p class="meta" style="margin-top:12px">Example account — this is what an artist’s profile looks like. Sign up on the Sell page and this page becomes yours. Already have an account on this device? <a class="text-link" href="#/login">LOG IN →</a></p>':'')+'<div class="two-col" style="margin-top:20px;align-items:start"><div>'+(example?'':'<div class="panel" style="margin-bottom:16px"><h3>EDIT YOUR PROFILE</h3><p class="sub" style="margin:8px 0 12px;font-size:13px">Your bio and profile picture pass an <b style="color:#fff">AI safety check</b> before they appear — nothing public goes up unscreened.</p><form id="profileForm"><label for="pfPic" style="display:block;font-size:12px;font-weight:900;margin-bottom:8px">PROFILE PICTURE</label><input id="pfPic" class="field" type="file" accept="image/*" style="margin-bottom:6px"><p class="form-note" style="margin-bottom:12px">JPG or PNG, up to 8 MB. Square pictures frame best.</p><label for="pfBio" style="display:block;font-size:12px;font-weight:900;margin-bottom:8px">YOUR BIO</label><textarea id="pfBio" class="field" maxlength="300" rows="3" placeholder="Tell the world who you are…">'+safe(get(STORE.profile,{}).bio||'')+'</textarea><p class="form-note" style="margin:6px 0 12px">Up to 300 characters. Keep contact details out of your bio — conversations stay here, where they\'re protected.</p><button class="primary" type="submit" style="width:100%">SAVE — RUN THE SAFETY CHECK</button><p id="pfMsg" style="margin-top:10px;line-height:1.6" role="alert"></p></form></div>')+'<div class="panel" id="acct-intro" style="margin-bottom:16px"><h3>Intro</h3>'+(example?'<p style="line-height:1.75;margin-top:8px;font-style:italic">“I paint impossible color and friendly monsters. Commissions are open — message me and let\'s make something loud.”</p>':(get(STORE.profile,{}).bio?'<p style="line-height:1.75;margin-top:8px;font-style:italic">“'+safe(get(STORE.profile,{}).bio)+'”</p>':''))+'<p style="line-height:1.9;margin-top:8px">🎨 '+(example?'Digital artist painting impossible color':'Independent artist studio')+'<br>📍 '+(example?'Austin, Texas':'Painted Python')+'<br>🐍 Member of the Serpent Circle'+(pr?'<br>🗣 Pronouns: '+safe(pr):'')+'<br>✦ Joined Painted Python 2026<br>🛡 Age band shown publicly — never a birthdate. Minor accounts get extra protections.</p></div><div class="panel" id="acct-reviews" style="margin-bottom:16px"><h3>Rating &amp; reviews</h3>'+(rating?'<div style="margin-top:8px">'+stars(rating.r)+' <b style="color:#fff">'+rating.r+'</b><p class="meta">'+rating.n+' customer reviews</p></div><p style="line-height:1.65;font-style:italic;margin-top:10px">“'+safe((REVIEWS['Nova Reyes']||[])[0].q)+'”</p><p class="meta">— Maya R. · Custom portrait</p>':'<p class="sub" style="margin-top:8px">No ratings yet — your first sale starts your climb to World Serpent.</p>')+'</div><div class="panel"><h3>Photos</h3><div style="display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:10px">'+photos.map(a=>'<div style="border-radius:10px;height:74px;display:flex;align-items:center;justify-content:center;font-size:30px;background:'+a.bg+'">'+a.symbol+'</div>').join('')+'</div></div></div><div><div id="acct-feed">'+(mine.length||example?posts:'<div class="panel" style="margin-bottom:16px"><p class="sub">No posts yet. Your stage is empty — for about five minutes.</p><div class="actions" style="margin-top:12px"><a class="primary" href="#/sell" style="text-decoration:none;padding:12px 18px;border-radius:12px">LIST YOUR FIRST MASTERPIECE ↗</a></div></div>')+'</div><div class="panel" id="acct-orders"><h3>Recent orders</h3>'+(example?'<p style="line-height:1.9;margin-top:8px">• <b style="color:#fff">Chromatic Serpent</b> — delivered ✔ Maya R. left a ★★★★★ review<br>• <b style="color:#fff">Custom portrait</b> — in the studio, ships Friday<br>• <b style="color:#fff">Neon Botanica (print)</b> — delivered ✔</p>':'<p class="sub" style="margin-top:8px">No orders yet. When a customer buys your art, it lands here — with delivery status and their review.</p>')+'</div><div class="panel" style="margin-top:16px"><h3>My membership</h3><p style="line-height:1.8;margin-top:8px"><b style="color:#fff">Python</b> — $9.99/mo · 5% per sale<br>Unlimited listings · commissions · analytics</p><div class="actions" style="margin-top:10px"><a class="outline" href="#/membership" style="text-decoration:none;padding:11px 16px;border-radius:12px">MANAGE MEMBERSHIP</a></div><p class="form-note" style="margin-top:10px">Example view — billing is not active in this preview.</p></div></div></div></div></section>'}
function render(){let path=(location.hash||'#/').slice(1),parts=path.split('/');let page=parts[1]||'';let content=page==='explore'?explore():page==='saved'?explore(true):page==='art'?detail(parts[2]):page==='sell'?sell():page==='dashboard'?dashboard():page==='artists'?artists():page==='top'?topSellers():page==='login'?login():page==='account'?account():page==='membership'?membership():page==='creator'?creator():page==='messages'?messages():page==='cart'?basket():page===''?home():notFound();document.getElementById('app').innerHTML=header()+`<main id="main">${content}</main>`+footer();document.title=`${page?page.toUpperCase()+' — ':''}Painted Python · Slither Into Creativity`;bind()}
function bind(){document.querySelectorAll('[data-action]').forEach(button=>button.addEventListener('click',()=>{let action=button.dataset.action,id=Number(button.dataset.id),artist=button.dataset.artist;if(action==='start-selling')go('/sell');if(action==='cart')go('/cart');if(action==='account')go('/account');if(action==='login')go('/login');if(action==='theme'){let t=get(STORE.theme,'dark')==='light'?'dark':'light';set(STORE.theme,t);applyTheme();toast(t==='light'?'Light mode ☀️':'Dark mode 🌙')}if(action==='scrollto'){let t=document.getElementById(button.dataset.target);if(t)t.scrollIntoView({behavior:'smooth'})}if(action==='saved')go('/saved');if(action==='messages')go('/messages');if(action==='category'){state.category=button.dataset.cat;state.query='';go('/explore')}if(action==='like'){let a=likes();set(STORE.likes,a.includes(id)?a.filter(x=>x!==id):[...a,id]);render();toast('Saved artwork updated ♡')}if(action==='add'){let a=cart();if(a.includes(id))toast('Already in your cart');else{set(STORE.cart,[...a,id]);render();toast('Added to your cart ✦')}}if(action==='remove'){set(STORE.cart,cart().filter(x=>x!==id));render();toast('Removed from cart')}if(action==='contact'){state.chatTo=artist;go('/messages')}if(action==='chat'){state.chatTo=artist;render()}if(action==='delete'){if(confirm('Delete this demo artwork?')){set(STORE.listings,get(STORE.listings,[]).filter(a=>a.id!==id));render();toast('Demo listing deleted')}}if(action==='signup-reset'){localStorage.removeItem(STORE.signup);render();toast('Sign-up cleared')}if(action==='logout'){localStorage.removeItem(STORE.signup);go('/');toast('Logged out — see you soon 🐍')}if(action==='checkout')toast('Demo only — connect a payment provider to activate checkout');if(action==='tier'){if(button.dataset.tier==='Hatchling')go('/explore');else{toast('Membership billing is not active in this prototype');go('/sell')}}}));let s=document.getElementById('searchArt');if(s)s.addEventListener('input',e=>{let p=e.target.selectionStart;state.query=e.target.value;render();let next=document.getElementById('searchArt');next.focus();next.setSelectionRange(p,p)});let c=document.getElementById('catArt');if(c)c.addEventListener('change',e=>{state.category=e.target.value;render()});let sort=document.getElementById('sortArt');if(sort)sort.addEventListener('change',e=>{state.sort=e.target.value;render()});let f=document.getElementById('listingForm');if(f)f.addEventListener('submit',e=>{e.preventDefault();let d=new FormData(f),artist=String(d.get('artist')).trim(),title=String(d.get('title')).trim(),price=Number(d.get('price'));if(!artist||!title||!Number.isFinite(price)||price<1||price>100000){toast('Please enter a valid artist, title, and price');return}let listing={id:Date.now(),artist,title,price,category:d.get('category'),medium:d.get('medium')||'Artist original',symbol:d.get('symbol'),bg:d.get('bg'),tag:'Just listed',description:d.get('description')};set(STORE.listings,[...get(STORE.listings,[]),listing]);set(STORE.seller,{artist});toast('Your demo artwork is live!');go('/dashboard')});let pf=document.getElementById('profileForm');if(pf)pf.addEventListener('submit',e=>{e.preventDefault();let bio=String(document.getElementById('pfBio').value||'').trim();let msg=document.getElementById('pfMsg');let flag=function(t){msg.textContent=t;msg.style.color='#FF8FA3'};let bc=bioCheck(bio);if(!bc.ok){flag(bc.why==='contact'?'🛡 Your bio includes contact details (an email, phone number, or link). For everyone\'s safety — especially younger artists — contact info can\'t appear in bios, so nothing was posted. Conversations stay here, where they\'re protected.':'🛡 Our safety check flagged words in your bio, so it hasn\'t been posted. Your art can be as wild as you are — the words just stay welcoming. Try a kinder wording.');return}let fileEl=document.getElementById('pfPic');let file=fileEl&&fileEl.files?fileEl.files[0]:null;let pc=picCheck(file);if(!pc.ok){flag(pc.why==='size'?'That image is over 8 MB — try a smaller copy.':'That file isn\'t an image we can use — try a JPG or PNG.');return}msg.textContent='🛡 AI safety check running…';msg.style.color='#FFD76A';let prev=get(STORE.profile,{});let finish=function(av){set(STORE.profile,{bio:bio,avatar:av||prev.avatar||null,at:Date.now()});render();toast('Profile saved — passed the safety check ✔')};if(!file){finish(null);return}let reader=new FileReader();reader.onload=function(){let img=new Image();img.onload=function(){let cv=document.createElement('canvas');let sc=Math.min(1,400/Math.max(img.width,img.height));cv.width=Math.max(1,Math.round(img.width*sc));cv.height=Math.max(1,Math.round(img.height*sc));cv.getContext('2d').drawImage(img,0,0,cv.width,cv.height);finish(cv.toDataURL('image/jpeg',.85))};img.onerror=function(){flag('That image couldn\'t be read — try a different file.')};img.src=reader.result};reader.readAsDataURL(file)});
let lf=document.getElementById('loginForm');if(lf)lf.addEventListener('submit',e=>{e.preventDefault();let d=new FormData(lf),email=String(d.get('email')||'').trim().toLowerCase(),username=String(d.get('username')||'').trim().toLowerCase();let known=get(STORE.known,null);let msg=document.getElementById('loginMsg');if(known&&email===String(known.email||'').toLowerCase()&&username===String(known.username||'').toLowerCase()){set(STORE.signup,{email:known.email,dob:known.dob,pronouns:known.pronouns,username:known.username,at:Date.now()});go('/account');toast('Welcome back, @'+(known.username||'')+' ✦')}else{msg.textContent='That email and username don\'t match the account on this device. New here? Create your account on the Sell page \u2014 it takes about a minute.';msg.style.color='#FF8FA3'}});
let su=document.getElementById('signupForm');if(su)su.addEventListener('submit',e=>{e.preventDefault();let d=new FormData(su),email=String(d.get('email')||'').trim(),dob=String(d.get('dob')||'');let msg=document.getElementById('signupMsg');let fail=function(t){msg.textContent=t;msg.style.color='#FF8FA3'};if(!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)){fail('Please enter a valid email address.');return}let age=ageFromDob(dob,new Date());if(age===null){fail('Please enter your real date of birth — we use it only to check the 13+ rule.');return}if(age<13){fail('Painted Python is for teenagers and adults only (13+), so we can\u2019t create your account yet. Keep making art — the stage will be here when you turn 13.');return}let pronouns=String(d.get('pronouns')||'');if(['She/Her','He/Him','They/Them'].indexOf(pronouns)<0){fail('Please choose your pronouns.');return}let username=String(d.get('username')||'').trim();let uc=usernameCheck(username);if(!uc.ok){fail(uc.why==='short'?'Usernames are 3\u201320 characters long.':uc.why==='chars'?'Usernames use letters, numbers, dots and underscores \u2014 and start with a letter.':uc.why==='bad'?'That username isn\u2019t allowed \u2014 it contains a word we don\u2019t host here. Try a clean variation that\u2019s uniquely you.':uc.why==='reserved'?'That name is reserved for the Painted Python team.':'That username is already taken \u2014 try adding a number or your favorite art word.');return}set(STORE.signup,{email:email,dob:dob,pronouns:pronouns,username:username,at:Date.now()});set(STORE.known,{email:email,dob:dob,pronouns:pronouns,username:username});render();toast('Account created — welcome to Painted Python \u2726')});
let chat=document.getElementById('chatForm');if(chat)chat.addEventListener('submit',e=>{e.preventDefault();let val=chat.elements.text.value.trim();if(!val)return;let box=get(STORE.messages,{});box[state.chatTo]=[...(box[state.chatTo]||[]),{text:val,at:Date.now()}];set(STORE.messages,box);render();toast('Saved in your local demo inbox — not delivered')})}
window.addEventListener('hashchange',()=>{window.scrollTo(0,0);render()});render();

window.keepCalc=function(v){var p=Number(v)||0;document.getElementById('keepVal').textContent=p;var f=function(pct){return '$'+Math.round(p*(1-pct/100))};document.getElementById('keepH').textContent=f(8);document.getElementById('keepP').textContent=f(5);document.getElementById('keepV').textContent=f(3)};

// Preview-proof navigation: tabs are links whose default action is a hash change,
// which some preview windows swallow. Intercept and route through go() instead.
document.addEventListener('click',function(e){var a=e.target&&e.target.closest?e.target.closest('a[href^="#/"]'):null;if(!a)return;e.preventDefault();go(a.getAttribute('href').slice(1));});
